assert.deepEqual(JSON.parse(frozenRaw['ioi2016-audit']),frozen.audits['data/corpus-audits/ioi-2016.json']);

function rawWalk(graphs, choices, entry) {
  const byId=new Map(graphs.map(graph=>[graph.id,graph]));
  let graph=byId.get(entry), node=graph.nodes.find(node=>node.id===graph.root), consumed=0;
  const steps=[], texts=[], visited=new Set();
  for(let budget=0;;++budget){
    assert(budget<1000,'independent raw replay terminates');
    if(node.type==='route'){
      const route=graph.id+'/'+node.id;assert(!visited.has(route),'independent route cycle');visited.add(route);
      graph=byId.get(node.graph);assert(graph,'raw route graph exists');node=graph.nodes.find(node=>node.id===graph.root);continue;
    }
    if(node.type!=='question'||consumed===choices.length)break;
    let answer=choices[consumed], consume=true;
    if(node.id===graph.root && !options(node).some(option=>option.id===answer) && graph.legacyEntryChoices?.[answer]){
      answer=graph.legacyEntryChoices[answer].answer;consume=false;
    }
    const option=options(node).find(option=>option.id===answer);assert(option,'independent raw answer exists');
    const target=node.answers[answer];
    steps.push({graph:graph.id,node:node.id,answer,target});
    texts.push({graph:graph.id,node:node.id,question:node.title,answer,answerLabel:option.label,target});
    node=graph.nodes.find(node=>node.id===target);assert(node,'raw target exists');if(consume)++consumed;
  }
  return {graph:graph.id,node:node.id,type:node.type,title:node.title,techniques:node.techniques??[],steps,texts,consumed};
}
let temporary;
const implementation=(async()=>{
  temporary=await mkdtemp(path.join(tmpdir(),'flowchartcp-ioi2016-railroad-flow-'));
  await compileFlowEntries();
  return {flow:await import(pathToFileURL(path.join(temporary,'flow.js'))),viewer:await import(pathToFileURL(path.join(temporary,'diagram-viewer.js')))};
})();
after(async()=>{await implementation;await rm(temporary,{recursive:true,force:true});});
async function collections(pattern){return(await Promise.all((await readdir(path.join(site,'data'))).filter(name=>pattern.test(name)).map(name=>json('data/'+name)))).flat();}
function walk(flow, choices, domain){const value=flow.walkFromRoot(choices,domain);assert.equal(value.consumed,choices.length);return value;}
function enter(flow,state){for(let budget=0;flow.evaluateState(state).current.type==='route';++budget){assert(budget<100);state=flow.enterFlowRoute(state);}return state;}
function replay(flow,choices,domain){let state=flow.initialState(domain);for(const answer of choices)state=flow.answerState(enter(flow,state),answer);return enter(flow,state);}
function weight(state){return state.answers.length+(state.trail??[]).reduce((sum,context)=>sum+context.answers.length+1,0);}
const svgCache=new Map();let html;
function svgFor(flow,graph){if(svgCache.has(graph.id))return svgCache.get(graph.id);
  const svg=flow.renderFlowSvg(graph);let count=0;
  for(const node of graph.nodes){assert(svg.includes(`data-node="${node.id}"`));
    if(node.type==='question')for(const option of flow.getNodeOptions(node)){
      ++count;assert(svg.includes(`data-edge="${node.id}:${option.id}:${node.answers[option.id]}"`));
      assert(svg.includes(`<title>${xml(option.label)}</title>`),'full SVG answer label');}
    if(node.type==='result')for(const id of node.techniques??[])assert(svg.includes(`href="/flowchartcp/techniques/${id}/"`));}
  assert.equal((svg.match(/class="flow-edge /g)??[]).length,count);svgCache.set(graph.id,svg);return svg;
}
function historical(fresh,old,label){
  assert.deepEqual(fresh.records.map(row=>row.problemId),old.records.map(row=>row.problemId),label+': fixed identities');
  for(const [key,value] of Object.entries(old))if(key!=='records'){
    assert(Object.hasOwn(fresh,key),label+': existing top field '+key);
    assert.equal(digest(fresh[key]),digest(value),label+': deep preserve '+key);}
  const projected=structuredClone(fresh);
  projected.records=fresh.records.map((row,index)=>{
    const initial=old.records[index],copy={};
    for(const key of Object.keys(initial)){assert(Object.hasOwn(row,key),label+'/'+row.problemId+': existing row field '+key);copy[key]=row[key];}
    assert.equal(digest(copy),digest(initial),label+'/'+row.problemId+': every prior field including prior resolutions');return copy;
  });
  return projected;
}

for(const current of cases){
  test(current.problemId+': every guard gates the sole technique; all six no/unknown routes remain unresolved',async()=>{
    const {flow}=await implementation;assert.deepEqual(flow.validateGraphs(),[]);assert.equal(flow.getGraph(current.domain).entry,true);
    assert.equal(flow.getFlowDomainId(flow.initialState(current.graph)),current.domain);
    const parent=walk(flow,current.prefix.slice(0,-1),current.domain);assert.equal(parent.graph.id,current.parent);assert.equal(parent.current.id,current.parentNode);
    const option=flow.getNodeOptions(parent.current).find(option=>option.id===current.prefix.at(-1));
    assert.deepEqual(option,{id:current.prefix.at(-1),label:current.parentLabel});
    const route=flow.getNode(parent.graph,parent.current.answers[option.id]);assert.equal(route.type,'route');assert.equal(route.graph,current.graph);
    for(let i=0;i<3;++i){const value=walk(flow,[...current.prefix,...Array(i).fill('yes')],current.domain);
      assert.equal(value.graph.id,current.graph);assert.equal(value.current.id,current.guards[i].id);assert.equal(value.current.type,'question');
      assert.deepEqual([value.current.title,value.current.explanation],[current.guards[i].title,current.guards[i].explanation]);
      assert.notEqual(value.graph.entry,true);assert(!candidates(value).includes(current.id));
      assert.deepEqual(flow.getNodeOptions(value.current).map(option=>option.id).sort(),['no','unknown','yes']);
      for(const answer of ['no','unknown']){const no=walk(flow,[...current.prefix,...Array(i).fill('yes'),answer],current.domain);
        assert.equal(no.graph.id,'condition-check');assert.equal(no.current.type,'question');assert(!candidates(no).includes(current.id));}}
    const yes=walk(flow,[...current.prefix,'yes','yes','yes'],current.domain);assert.equal(yes.current.type,'result');assert.deepEqual(candidates(yes),[current.id]);
    const occurrences=flow.graphs.flatMap(graph=>graph.nodes.filter(node=>(node.techniques??[]).includes(current.id)).map(node=>({graph:graph.id,node:node.id,type:node.type})));
    assert.deepEqual(occurrences,[{graph:current.graph,node:'result',type:'result'}]);
  });
  test(current.problemId+': both displays, complete SVG labels, article links, shared URLs and Back retain each premise',async()=>{
    const {flow,viewer}=await implementation;html??=flow.renderFlowHtml('/flowchartcp/');assert(html.includes('data-view="questions"')&&html.includes('data-view="diagram"'));
    for(const graphId of new Set([current.domain,current.parent,current.graph])){const graph=flow.getGraph(graphId);svgFor(flow,graph);assert(html.includes(`data-graph-panel="${graphId}"`));
      for(const node of graph.nodes){assert(html.includes(`id="flow-text-${graphId}-${node.id}"`));assert(html.includes(xml(node.title)));
        if(node.type==='question')for(const option of flow.getNodeOptions(node)){
          assert(html.includes(xml(option.label)));assert(html.includes(`#flow-text-${graphId}-${node.answers[option.id]}`));}}}
    assert(html.includes(`/flowchartcp/techniques/${current.id}/`));
    const histories=[[...current.prefix,'yes','yes','yes']];for(let i=0;i<3;++i)for(const answer of ['no','unknown'])histories.push([...current.prefix,...Array(i).fill('yes'),answer]);
    for(const choices of histories){let state=replay(flow,choices,current.domain);assert.deepEqual(flow.evaluateState(state).current,walk(flow,choices,current.domain).current);
      for(let remaining=weight(state)+1;;--remaining){assert(remaining>0);assert.equal(flow.getFlowDomainId(state),current.domain);assert.deepEqual(flow.sanitizeState(state),state);
        const value=flow.evaluateState(state),svg=svgFor(flow,value.graph);for(const node of value.path)assert(svg.includes(`data-node="${node.id}"`));
        for(const edge of value.edges)assert(svg.includes(`data-edge="${edge.from}:${edge.answer}:${edge.to}"`));
        const hash=flow.serializeFlowHash(state);assert.deepEqual(flow.parseFlowHash(hash),state);assert.deepEqual(viewer.diagramState(state.graph,hash),state);
        const url=new URL(viewer.diagramViewerUrl(state.graph,'/flowchartcp/',state),'https://flowchartcp.test');assert.equal(url.pathname,`/flowchartcp/diagrams/${state.graph}/`);assert.equal(url.hash,hash);
        if(!weight(state))break;const previous=flow.backFlowState(state);assert(weight(previous)<weight(state));state=previous;}
      assert.deepEqual(state,flow.initialState(current.domain));assert.deepEqual(flow.backFlowState(state),state);}
  });
  test(current.problemId+': grouped metadata, date precision, source bounds, actual visible C++ fence and canonical example agree',async()=>{
    const {flow}=await implementation;const [techniques,references,features,walks]=await Promise.all([collections(/^techniques-.*\.json$/),collections(/^references-.*\.json$/),json(current.feature),json('data/problem-walks.json')]);
    const registered=techniques.filter(row=>row.id===current.id);assert.equal(registered.length,1);const metadata=registered[0];
    assert.equal(metadata.kind,'technique');assert.equal(metadata.status,'reviewed');assert.deepEqual(metadata.entryPoints,['advanced','complexity','reasoning']);
    assert(metadata.aliases.some(value=>/[A-Za-z]/.test(value)));for(const id of metadata.prerequisites)assert(techniques.some(row=>row.id===id));
    assert((await json('data/techniques-specific-'+current.group+'.json')).some(row=>row.id===current.id));
    assert((await json('data/references-specific-'+current.group+'.json')).some(row=>row.techniqueId===current.id&&match(row,current)));
    const article=await readFile(path.join(site,'src/content/docs/techniques',current.id+'.mdx'),'utf8');
    assert.deepEqual([...article.matchAll(/^## (.+)$/gm)].map(m=>m[1]),heads);
    const title=article.match(/^title:\s*(.+)$/m)?.[1],description=article.match(/^description:\s*(.+)$/m)?.[1];
    assert.equal(JSON.parse(title),metadata.title);assert.equal(JSON.parse(description),metadata.summary);
    const fences=[...article.matchAll(/^```cpp\s*\n(.*?)^```\s*$/gms)];assert.equal(fences.length,1);assert.equal(bytesHash(fences[0][1]),current.cppSha256);
    assert(!/<(?:details|summary)\b/i.test(article));assert(article.includes(current.sourceFunction));assert(article.includes(`techniqueId="${current.id}"`));
    assert(!/\]\(\/flowchart\//.test(article),'all internal links have current base');for(const source of metadata.sources)assert(article.includes(source),'every metadata source visible in article');
    const checker=await readFile(path.join(site,current.checker),'utf8');assert(checker.includes(current.id+'.mdx'));assert(checker.includes('re.findall')&&checker.includes(current.sourceFunction));
    const refs=references.filter(row=>row.techniqueId===current.id&&match(row,current));assert.equal(refs.length,1);const reference=refs[0];
    assert.equal(reference.url,current.statement);assert.equal(reference.editorialUrl,current.editorial);assert.equal(reference.verification,'independent-analysis');
    assert.equal(reference.sourceDate,current.sourceDate);assert.equal(reference.sourceDatePrecision??reference.datePrecision,current.precision);assert.equal(reference.difficulty,null);
    assert.equal(reference.cutoffVerification,'contest-before-cutoff');assert(reference.evidence.trim());assert(!/ASan|checksum|checks|テスト件数/.test(reference.evidence));
    assert.equal(features.length,1);const feature=features[0];assert(match(feature,current));assert.deepEqual(feature.techniqueIds,[current.id]);
    assert.equal(feature.url,current.statement);assert.equal(feature.evidenceUrl,current.editorial);assert.equal(feature.reviewStatus,'verified');assert.equal(feature.verification,'independent-analysis');
    assert.equal(feature.publicationDate,current.sourceDate);assert.equal(feature.publicationDatePrecision,current.precision);assert.equal(feature.publicationYear,2016);assert.equal(feature.exactDateVerified,current.exactDate);
    assert.equal(feature.originalNumericBoundsVerified,true);assert.equal(feature.difficulty,null);assert.equal(reference.exactDateVerified,current.exactDate);
    const examples=walks.filter(row=>match(row,current)&&row.expectedTechniqueIds.includes(current.id));assert.equal(examples.length,1);const example=examples[0];
    assert.equal(example.entryGraphId,current.domain);assert.deepEqual(example.choices,[...current.prefix,'yes','yes','yes']);assert.deepEqual(example.expectedTechniqueIds,[current.id]);
    assert.equal(example.statementUrl,current.statement);assert.equal(example.evidenceUrl,current.editorial);assert.equal(example.verificationKind,'independent-analysis');assert.equal(example.reviewStatus,'verified');
    assert.deepEqual(example.features,feature.features);assert.deepEqual(walk(flow,example.choices,current.domain).steps.map(({graph,node,answer})=>({graph,node,answer})),example.steps);
  });
}

test('all531 previous records and independently replayed terminals, targets, full questions and labels stay fixed',async()=>{
  const {flow}=await implementation;assert.equal(frozen.flows.length,477);assert.equal(frozen.flows.reduce((sum,g)=>sum+g.nodes.length,0),3733);assert.equal(frozen.walks.length,531);
  const walks=await json('data/problem-walks.json');assert(walks.length>=532);assert.equal(digest(walks.slice(0,531)),digest(frozen.walks));
  const raw=frozen.walks.map(row=>rawWalk(frozen.flows,row.choices,row.entryGraphId));
  const observed=frozen.walks.map(row=>{const value=flow.walkFromRoot(row.choices,row.entryGraphId);assert.equal(value.consumed,row.choices.length);
    for(const id of row.expectedTechniqueIds)assert(candidates(value).includes(id));
    return {graph:value.graph.id,node:value.current.id,type:value.current.type,title:value.current.title,techniques:candidates(value),steps:value.steps,
      texts:value.steps.map(step=>{const node=flow.getNode(flow.getGraph(step.graph),step.node);return{graph:step.graph,node:step.node,question:node.title,answer:step.answer,answerLabel:flow.getNodeOptions(node).find(option=>option.id===step.answer).label,target:step.target};}),consumed:value.consumed};});
  assert.equal(digest(observed),digest(raw),'product walking must equal independent frozen raw replay including every label/target/terminal');
});

test('all477 old graphs and3733 old nodes preserve every field, old option order, answer order and exact result',async()=>{
  const {flow}=await implementation;const oldIds=frozen.flows.map(g=>g.id);assert.deepEqual(flow.graphs.filter(g=>oldIds.includes(g.id)).map(g=>g.id),oldIds);
  for(const oldGraph of frozen.flows){const graph=flow.getGraph(oldGraph.id),oldNodeIds=oldGraph.nodes.map(n=>n.id),projected={};
    assert.deepEqual(graph.nodes.filter(n=>oldNodeIds.includes(n.id)).map(n=>n.id),oldNodeIds,oldGraph.id+': node ordering');
    for(const key of Object.keys(oldGraph)){assert(Object.hasOwn(graph,key),oldGraph.id+': graph field '+key);projected[key]=structuredClone(graph[key]);}
    projected.nodes=oldGraph.nodes.map(old=>{const node=graph.nodes.find(n=>n.id===old.id),copy={};for(const key of Object.keys(old)){
      assert(Object.hasOwn(node,key),graph.id+'/'+old.id+': node field '+key);copy[key]=structuredClone(node[key]);}
      if(old.answers){const keys=Object.keys(old.answers);assert.deepEqual(Object.keys(node.answers).filter(key=>keys.includes(key)),keys,graph.id+'/'+old.id+': answer order');
        copy.answers=Object.fromEntries(keys.map(key=>[key,node.answers[key]]));
        if(old.options){assert(Array.isArray(node.options));copy.options=node.options.filter(option=>keys.includes(option.id));}
        else if(node.options!==undefined){assert.deepEqual(node.options.filter(option=>keys.includes(option.id)),options(old));}}
      assert.equal(digest(stable(copy)),digest(stable(old)),graph.id+'/'+old.id+': complete old node');return copy;});
    assert.equal(digest(stable(projected)),digest(stable(oldGraph)),graph.id+': complete old graph');}
});

test('all593 old local prefixes and404 completed shares retain terminal candidates, domains and full Back histories',async()=>{
  const {flow,viewer}=await implementation;const fixture=await json('tests/fixtures/flow-legacy-sharing.json');
  assert.equal(digest(fixture),'0c4fe53421b48c94c0975fa1fcfcd4fac6eaeef084fea773450aafad5a32f83e');assert.equal(fixture.localPrefixes.length,593);assert.equal(fixture.completedWalks.length,404);
  for(const row of [...fixture.localPrefixes,...fixture.completedWalks]){let state=flow.parseFlowHash(row.hash);const node=flow.evaluateState(state).current;
    assert.equal(node.id,row.expected.id);assert.equal(node.type,row.expected.type);assert.deepEqual(node.techniques??[],row.expected.techniques);if(row.expected.routeGraph)assert.equal(node.graph,row.expected.routeGraph);
    for(let left=weight(state)+1;;--left){assert(left>0);assert.equal(flow.getFlowDomainId(state),row.domain);const hash=flow.serializeFlowHash(state);
      assert.deepEqual(flow.parseFlowHash(hash),state);assert.deepEqual(viewer.diagramState(state.graph,hash),state);if(!weight(state))break;
      const previous=flow.backFlowState(state);assert(weight(previous)<weight(state));state=previous;}
    assert.deepEqual(state,flow.initialState(row.domain));}
});

