  assert.equal(isCorpusSolutionReviewed(before),true);assert.equal(isCorpusSolutionReviewed(row),true);
  assert.equal(frozen.audits[current.audit].status.solutionReviewedCount,6);assert.equal(frozen.audits[current.audit].status.coveredCount,0);assert.equal(frozen.audits[current.audit].status.fullImplementationValidatedCount,0);
